CREATE TABLE CORE.T_FACT_SALES_RETURN_PACKAGE_SHIPMENT (
	RETURN_PACK_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier(surrogate key) for the package of the return',
	PROD_VARIANT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the product variant being returned',
	RETURN_REQUEST_NR VARCHAR(50) COMMENT 'Internal return request number, created by Lidl when a customer creates a return request.  Not every return request is turned into return order.',
	RETURN_PACK_TRACKING_NR VARCHAR(1000) COMMENT 'ID, which links the shipment of the return (from customer to Lidl Digital) with the actual package and can also be searched for within the the carrier url',
	RETURN_PACK_TRACKING_URL VARCHAR(500) COMMENT 'URL to track the return package shipment',
	SALE_ORDER_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the sales order',
	SALE_ORDER_NR VARCHAR(20) COMMENT 'The original order number of the source system',
	SALE_ORDER_POS_NR NUMBER(38,0) COMMENT 'The particular position number of an item in an order',
	DIST_CHANNEL_CD VARCHAR(5) COMMENT 'The code for the distribution channel ( a channel  through which the goods are sold )',
	HAULER_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for hauler',
	ORIGIN_COUNTRY_CD VARCHAR(5) COMMENT 'The unique code for a country from which the customer sends back the package(s) (according to ISO-3166 Alpha-2. E.g. \"DE\" for Germany or \"FR\" for France)',
	PACK_SIZE_HANDLE_GROUP_CD           VARCHAR(5)      COMMENT 'A code for packaging size classification grouped in the bigger buckets based on how many effort is required to handle it - '' 1 person''  , ''2 persons'' etc',
	RETURN_WH_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the warehouse handling the return.',
	RETURN_OPTION_CD VARCHAR(50) COMMENT 'Return option of the shipment, it can be LABEL or PICK_UP.',
	RETURN_REQUEST_TMSP TIMESTAMP_LTZ(9) COMMENT 'Time when the return request was made by the customer.',
	RETURN_REQUEST_DT DATE COMMENT 'Date when the return request was made by the customer.',
	HANDOVER_TO_CARRIER_TMSP TIMESTAMP_LTZ(9) COMMENT 'Time when the package is handed over to the carrier.',
	HANDOVER_TO_CARRIER_DT DATE COMMENT 'Date when the package is handed over to the carrier.',
	FIRST_INTAKE_SCAN_HUB_TMSP TIMESTAMP_LTZ(9) COMMENT 'Time of first hub scan in return logistics.',
	FIRST_INTAKE_SCAN_HUB_DT DATE COMMENT 'Date of first hub scan in return logistics.',
	RETURN_HUB_TMSP TIMESTAMP_LTZ(9) COMMENT 'Time when the package is returned to carrier hub.',
	RETURN_HUB_DT DATE COMMENT 'Date when the package is returned to carrier hub.',
	RETURN_WH_TMSP TIMESTAMP_LTZ(9) COMMENT 'Time when the package is returned to the Lidl warehouse.',
	RETURN_WH_DT DATE COMMENT 'Date when the package is returned to the Lidl warehouse.',
	PROD_QTY NUMBER(38,5) COMMENT 'Quantity of a particular product returned.',
	REQUEST_TO_CARRIER_DUR_DAY NUMBER(38,0) COMMENT 'Duration in days between the return request from the customer and the handover of the package to the carrier.',
	REQUEST_TO_CARRIER_DUR_HR NUMBER(31,6) COMMENT 'Duration in hours between the return request from the customer and the handover of the package to the carrier.',
	CARRIER_TO_HUB_DUR_DAY NUMBER(38,0) COMMENT 'Duration in days between the handover of the package to the carrier and the return of the package to the carrier hub.',
	CARRIER_TO_HUB_DUR_HR NUMBER(31,6) COMMENT 'Duration in hours between the handover of the package to the carrier and the return of the package to the carrier hub.',
	HUB_TO_WH_DUR_DAY NUMBER(38,0) COMMENT 'Duration in days between the arrival of the package at the carrier hub and the arrival of the package at the Lidl warehouse.',
	HUB_TO_WH_DUR_HR NUMBER(31,6) COMMENT 'Duration in hours between the arrival of the package at the carrier hub and the arrival of the package at the Lidl warehouse.',
	CARRIER_TO_WH_DUR_DAY NUMBER(38,0) COMMENT 'Duration in days between the handover of the package to the carrier and its arrival at the Lidl warehouse.',
	CARRIER_TO_WH_DUR_HR NUMBER(31,6) COMMENT 'Duration in hours between the handover of the package to the carrier and its arrival at the Lidl warehouse.',
	RETURN_SHIP_COST_NET_EUR_VAL NUMBER(38,5) COMMENT 'Lidl costs for shipping and transport (Return process)',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
	DWH_SRC_FILE_NAME VARCHAR(255) NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
	SRC_FILE_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',
	IS_LEGACY_FG BOOLEAN COMMENT 'Technical field used to identify legacy data for further use as a filter condition. Legacy data used to come from SAP, and the current data comes from carrier layer.',
	RETURN_PAYM_TO_CUST_TMSP TIMESTAMP_LTZ(9) COMMENT 'The timestamp when the payment is transferred to the customer in case of a returned item.',
   CONSTRAINT PK_T_FACT_SALES_RETURN_PACKAGE_SHIPMENT PRIMARY KEY (RETURN_PACK_SID, PROD_VARIANT_SID) NOT ENFORCED 
)  COMMENT = 'A fact table that contains one row for every package of return items sent back by a customer. Customer may place one order with one position for 5 T-shirts. Then he/she can return 2 t-shirts in one return packaged and 2 more shirts in another return package. ';
